import {writeFile} from 'node:fs/promises';
import {openBrowser} from 'vitexec/cli';
await writeFile('.cache/react-adapter-probe-entry.mjs',`export {createElement,StrictMode} from 'react';export {createRoot} from 'react-dom/client';export {createWorld} from '../src/native_runtime_api.ts';export {createReactNativeRootAdapter} from '../src/react_native_adapter.ts';export * from './react-native-adapter-fixture.mjs';`);
const b=await openBrowser({gpu:false});try{const ctx=await b.newContext({ignoreHTTPSErrors:true});const p=await ctx.newPage();p.on('pageerror',e=>console.log('PAGEERROR',e.message));await p.goto('https://async-transition-stress.localhost:1355/native-task-transitions.html',{waitUntil:'networkidle'});await p.evaluate(async()=>{const m=await import('/.cache/react-adapter-probe-entry.mjs');window.__probeModule=m;const w=m.createWorld();const log=[];w.subscribeChanges(c=>log.push(c));window.__probeLog=log;const A=m.createReactNativeRootAdapter(m.NativeButton,{world:w,profile:(name,ms)=>log.push({name,ms})});const host=document.createElement('div');host.id='independent-adapter';document.body.append(host);const r=m.createRoot(host);r.render(m.createElement(m.StrictMode,null,m.createElement(A,{label:'first',onAction:value=>log.push({action:value})})));window.__probeReactRoot=r;});await p.waitForFunction(()=>document.querySelector('#independent-adapter button'));await p.locator('#independent-adapter button').click();await p.waitForTimeout(100);console.log(await p.evaluate(()=>({text:document.querySelector('#independent-adapter button').textContent,active:window.__probeModule.activeEffects,setter:window.__probeModule.lastSetterResult,log:window.__probeLog})));await p.evaluate(()=>{window.__probeReactRoot.unmount();window.dispatchEvent(new Event('pagehide'));});}finally{await b.close();}
